export function softbankFundingSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !SOFTBANK_FUNDING_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Invalid SoftBank funding figure');
  }
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
